import random

def has_short_cycle(adj, max_len=7):
    # BFS from each vertex to detect cycles of length <= max_len
    n = len(adj)
    for s in range(n):
        # BFS
        dist = {s: 0}
        parent = {s: -1}
        queue = [s]
        while queue:
            new_queue = []
            for u in queue:
                if dist[u] > max_len // 2 + 1: continue
                for v in adj[u]:
                    if v not in dist:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        new_queue.append(v)
                    elif v != parent[u]:
                        # Found cycle
                        cyc_len = dist[u] + dist[v] + 1
                        if cyc_len <= max_len:
                            return True
            queue = new_queue
    return False

def girth(adj):
    n = len(adj)
    best = float('inf')
    for s in range(n):
        dist = {s: 0}
        parent = {s: -1}
        from collections import deque
        q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    cl = dist[u] + dist[v] + 1
                    if cl < best:
                        best = cl
    return best

# Try to build: start with empty, add edges greedily without creating cycle of length < 8
random.seed(42)

best_edges = 0
best_adj = None

for trial in range(200):
    n = 18
    adj = [set() for _ in range(n)]
    edges = []
    pairs = [(i,j) for i in range(n) for j in range(i+1,n)]
    random.shuffle(pairs)
    for i,j in pairs:
        # Check if adding creates cycle of length < 8
        # i.e., distance from i to j in current graph < 7
        from collections import deque
        d = {i: 0}
        q = deque([i])
        while q:
            u = q.popleft()
            if d[u] >= 6: continue
            for w in adj[u]:
                if w not in d:
                    d[w] = d[u]+1
                    q.append(w)
        if j not in d or d[j] >= 7:
            adj[i].add(j); adj[j].add(i)
            edges.append((i,j))
    if len(edges) > best_edges:
        best_edges = len(edges)
        best_adj = [set(a) for a in adj]
        best_edge_list = list(edges)
        print(f"Trial {trial}: {len(edges)} edges, girth={girth(adj)}")

print("Best:", best_edges)
